    let set = recipe_operations_graph()?;
    let _ = set;
    let root = &args.id;
    recipe_operations_graph_root(graphs, root).await?;
    let body: graph_routes::CommitInput = graph_routes::body(&args.input)?;
    let row = recipe_operations_graph_ref(graphs, principal.as_ref(), root, &args.r#ref, true).await?;
    let actor = actor(principal.as_ref())?;
    let options = engine::CommitOptions {
        message: body.message.unwrap_or_default(),
        tag: body.tag.unwrap_or(false),
    };
    let committed = graphs.recipe.commit(&actor, &row.id, body.version, &options).await.map_err(refused)?;
