/// recipe.merge (`POST /api/recipes/{id}/refs/{ref}/merge`): Recipe's merge (D138).
pub(crate) async fn recipe_merge(
    graphs: &Graphs,
    principal: Option<Principal>,
    args: RecipeMergeArgs,
) -> Result<types::RecipeGraphMergeResult, ApiError> {
    let set = recipe_operations_graph()?;
    let _ = set;
    let root = &args.id;
    recipe_operations_graph_root(graphs, root).await?;
    let body: graph_routes::MergeInput = graph_routes::body(&args.input)?;
    // The merge writes its target, so a target that is a change set is
    // held to the row rule as a save to it is; the source it reads.
    let source = recipe_operations_graph_ref(graphs, principal.as_ref(), root, &args.r#ref, false).await?;
    let actor = actor(principal.as_ref())?;
    let into: types::IdentityUUID = match (&body.into, &source.parent_ref_id) {
        (Some(into), _) => parse("a ref", into)?,
        (None, Some(parent)) => *parent,
        (None, None) => return Err(graph_routes::no_parent()),
    };
    let target = recipe_operations_graph_ref(graphs, principal.as_ref(), root, &into, false).await?;
    if target.parent_ref_id.is_some() {
        recipe_operations_graph_ref(graphs, principal.as_ref(), root, &into, true).await?;
    }
    let options = engine::CommitOptions {
        message: body.message.unwrap_or_default(),
        tag: body.tag.unwrap_or(false),
    };
    let resolutions = recipe_operations_graph_resolutions(&body.resolutions)?;
    let merged = graphs.recipe.merge(&actor, &source.id, &into, body.version, &resolutions, &options).await.map_err(refused)?;
    graph_routes::recode(recipe_operations_graph_merged(&merged))
}

